mapper.select:
SELECT COUNT("lr"."line_route_id") FROM "line_routes" "lr" JOIN "lines" "l" ON "l"."rosen_id" = "lr"."rosen_id" AND "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."rosen_id" = #{rosenId}
JOIN "agencies" "a" ON "a"."business_corp_id" = "l"."business_corp_id" AND "a"."available_flag" = 1
AND "a"."business_corp_id" = #{businessCorpId}
AND "a"."del_flag" = 0 WHERE "lr"."del_flag" = 0
AND "lr"."line_route_name" LIKE #{likeSearchLineRouteName}
AND "lr"."available_flag" = #{availableFlag}

SELECT "lr"."line_route_id" , "lr"."line_route_name" , "lr"."service_start_date" , "lr"."service_end_date" , "lr"."available_flag" , "l"."rosen_name" FROM "line_routes" "lr" JOIN "lines" "l" ON "l"."rosen_id" = "lr"."rosen_id" AND "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."rosen_id" = #{rosenId}
JOIN "agencies" "a" ON "a"."business_corp_id" = "l"."business_corp_id" AND "a"."available_flag" = 1
AND "a"."business_corp_id" = #{businessCorpId}
AND "a"."del_flag" = 0 WHERE "lr"."del_flag" = 0
AND "lr"."line_route_name" LIKE #{likeSearchLineRouteName}
AND "lr"."available_flag" = #{availableFlag}
ORDER BY "lr"."line_route_id" LIMIT #{displayNum} OFFSET #{startRowNum}

mapper.insert:
INSERT INTO "line_routes" ( "rosen_id", "line_route_code", "service_start_date", "service_end_date", "line_route_name", "line_route_short_name", "line_route_number", "line_route_number_en", "line_detail_service_division", "main_stopover_point", "line_route_url", "line_route_color", "line_route_text_color", "line_route_remarks", "available_flag"
) VALUES ( #{rosenId}, #{lineRouteCode}, CAST(#{serviceStartDate} AS date), CAST(#{serviceEndDate} AS date), #{lineRouteName}, #{lineRouteShortName}, #{lineRouteNumber}, #{lineRouteNumberEn}, #{lineDetailServiceDivision}, #{mainStopoverPoint}, #{lineRouteUrl}, #{lineRouteColor}, #{lineRouteTextColor}, #{lineRouteRemarks}, #{availableFlag}
)

