SELECT "l"."rosen_code" , "ag"."operation_company_no" , "lr"."line_route_code" , "lr"."line_route_color" , "lr"."line_route_number" , "lr"."line_route_number_en" , "lr"."line_route_remarks" , "lr"."line_route_short_name" , "lr"."line_route_text_color" , "lr"."line_route_url" FROM "line_routes" AS "lr" INNER JOIN "lines" AS "l" ON "l"."del_flag" = 0 AND "l"."available_flag" = 1 AND "l"."rosen_id" = "lr"."rosen_id" INNER JOIN "agencies" AS "ag" ON "ag"."del_flag" = 0 AND "ag"."available_flag" = 1 AND "ag"."business_corp_id" = "l"."business_corp_id" WHERE "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."rosen_id" IN
#{id}
ORDER BY "lr"."line_route_id" ASC
